// Generated by axum_dsl 0.1.0 from notes.axum.rb. Do not edit.
#[derive(serde::Serialize, serde::Deserialize)]
struct NewNote {
    body: String,
}

#[derive(serde::Serialize, serde::Deserialize)]
struct NoteId {
    id: i64,
}

// HTML escaping for a view's `{{ name }}`, written into the render's buffer: written by the compiler
fn axum_dsl_html_escape_into(out: &mut String, input: &str) {
    let mut copied = 0;
    for (i, c) in input.char_indices() {
        let replacement = match c {
            '&' => "&amp;",
            '<' => "&lt;",
            '>' => "&gt;",
            '"' => "&quot;",
            '\'' => "&#39;",
            _ => continue,
        };
        out.push_str(&input[copied..i]);
        out.push_str(replacement);
        copied = i + c.len_utf8();
    }
    out.push_str(&input[copied..]);
}

#[derive(Clone, serde::Serialize)]
struct Note {
    id: i64,
    body: String,
    created_at: String,
    tag: Option<String>,
}

impl Note {
    fn from_row(__r: &rusqlite::Row<'_>) -> rusqlite::Result<Note> {
        Ok(Note { id: __r.get("id")?, body: __r.get("body")?, created_at: __r.get("created_at")?, tag: __r.get("tag")? })
    }
}

// the database (database :sqlite): the writer and reader threads, the startup checks and the statements below are written by the compiler
// DB_WRITES says, per DB_STATEMENTS entry, whether the statement writes (sqlite3_stmt_readonly, so a RETURNING write counts).
static DB_WRITES: std::sync::OnceLock<Vec<bool>> = std::sync::OnceLock::new();

// Every write (a statement DB_WRITES marks, and every transaction) is a boxed closure sent to ONE writer thread that owns
// one connection and runs them in arrival order, back to back, as once-campfire-rust/crates/db/src/database.rs does:
// writers queue in the process instead of in SQLite's busy handler (which sleeps 1 to 100 ms between retries), and no
// async lock is held across a thread hand-off. The reply comes back on a oneshot, like a read's.
type DbWrite = Box<dyn FnOnce(&mut rusqlite::Connection) + Send>;
static DB_WRITER: std::sync::OnceLock<std::sync::mpsc::Sender<DbWrite>> = std::sync::OnceLock::new();

// Reads run on threads of their own, not tokio's blocking pool, as in once-campfire-rust/crates/db/src/database.rs: there a read
// that found every connection busy parked a blocking thread, while here a waiting read costs a queue entry and a reader
// that finishes takes the next read without a hand-off. One queue, DB_READERS threads, each with its own query_only connection.
const DB_READERS: usize = 5;
type DbRead = Box<dyn FnOnce(&mut rusqlite::Connection) + Send>;
struct DbReadQueue {
    jobs: std::sync::Mutex<std::collections::VecDeque<DbRead>>,
    ready: std::sync::Condvar,
}
static DB_READS: std::sync::OnceLock<DbReadQueue> = std::sync::OnceLock::new();

fn db_reader(mut __c: rusqlite::Connection) {
    let queue = DB_READS.get().expect("the read queue is set before its readers start");
    loop {
        let job = {
            let mut jobs = queue.jobs.lock().unwrap_or_else(|p| p.into_inner());
            loop {
                if let Some(job) = jobs.pop_front() {
                    break job;
                }
                jobs = queue.ready.wait(jobs).unwrap_or_else(|p| p.into_inner());
            }
        };
        job(&mut __c);
    }
}

// Sends `work` to the writer thread and waits for its answer; an error names the `kind` (query or transaction) and `name`.
// A panic in `work` is caught on the writer thread (as a reader does), so it answers this caller and the thread lives on.
async fn db_write<T: Send + 'static>(
    kind: &'static str,
    name: &'static str,
    work: impl FnOnce(&mut rusqlite::Connection) -> rusqlite::Result<T> + Send + 'static,
) -> Result<T, String> {
    let (tx, rx) = tokio::sync::oneshot::channel();
    let job: DbWrite = Box::new(move |__c| {
        let __out = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| work(__c)));
        let _ = tx.send(__out);
    });
    let Some(writer) = DB_WRITER.get() else {
        return Err(format!("{kind} `{name}`: the database writer is gone"));
    };
    if writer.send(job).is_err() {
        return Err(format!("{kind} `{name}`: the database writer is gone"));
    }
    match rx.await {
        Ok(Ok(out)) => out.map_err(|e| format!("{kind} `{name}`: {e}")),
        Ok(Err(_)) => Err(format!("{kind} `{name}`: the write panicked")),
        Err(_) => Err(format!("{kind} `{name}`: the database writer is gone")),
    }
}

// Runs the statement DB_STATEMENTS[index]: a read on a reader thread, a write on the writer thread; an error names the query.
async fn db_run<T: Send + 'static>(
    index: usize,
    name: &'static str,
    work: impl FnOnce(&mut rusqlite::Connection) -> rusqlite::Result<T> + Send + 'static,
) -> Result<T, String> {
    if let (true, Some(queue)) = (DB_WRITES.get().is_some_and(|w| !w[index]), DB_READS.get()) {
        let (tx, rx) = tokio::sync::oneshot::channel();
        let job: DbRead = Box::new(move |__c| {
            let __out = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| work(__c)));
            let _ = tx.send(__out);
        });
        queue.jobs.lock().unwrap_or_else(|p| p.into_inner()).push_back(job);
        queue.ready.notify_one();
        return match rx.await {
            Ok(Ok(out)) => out.map_err(|e| format!("query `{name}`: {e}")),
            Ok(Err(_)) => Err(format!("query `{name}`: the read panicked")),
            Err(_) => Err(format!("query `{name}`: the database reader is gone")),
        };
    }
    db_write("query", name, move |__c| {
        let __out = work(__c)?;
        db_after_write(__c);
        Ok::<T, rusqlite::Error>(__out)
    })
    .await
}

async fn db_open() -> Result<(), String> {
    let path = match std::env::var("DATABASE_PATH") {
        Ok(value) if !value.is_empty() => value,
        _ => "notes.sqlite3".to_string(),
    };
    let mut __writer = rusqlite::Connection::open(&path).map_err(|e| format!("database {path}: cannot open it: {e}"))?;
    db_connection_setup(&mut __writer).map_err(|e| format!("database {path}: {e}"))?;
    let (__send, __jobs) = std::sync::mpsc::channel::<DbWrite>();
    std::thread::Builder::new()
        .name("db-writer".into())
        .spawn(move || {
            while let Ok(job) = __jobs.recv() {
                job(&mut __writer);
            }
        })
        .map_err(|e| format!("database {path}: cannot start the writer: {e}"))?;
    // The startup checks and migrations run on the writer's connection, as its first job.
    let (__done, __started) = tokio::sync::oneshot::channel();
    let __job: DbWrite = Box::new(move |__c| {
        let _ = __done.send(db_startup(__c));
    });
    __send.send(__job).map_err(|_| format!("database {path}: the writer stopped during startup"))?;
    let _ = DB_WRITER.set(__send);
    __started.await.map_err(|_| format!("database {path}: the writer stopped during startup"))??;
    let (__wake, __woken) = std::sync::mpsc::sync_channel::<()>(1);
    let mut __checkpointer = rusqlite::Connection::open(&path).map_err(|e| format!("database {path}: cannot open the checkpointer connection: {e}"))?;
    db_connection_setup(&mut __checkpointer).map_err(|e| format!("database {path}: {e}"))?;
    std::thread::Builder::new()
        .name("db-checkpointer".into())
        .spawn(move || {
            while __woken.recv().is_ok() {
                let _running = DB_CHECKPOINT_RUNNING.lock().unwrap_or_else(|p| p.into_inner());
                db_checkpoint(&__checkpointer, "PASSIVE");
            }
        })
        .map_err(|e| format!("database {path}: cannot start the checkpointer: {e}"))?;
    let _ = DB_WAKE.set(__wake);
    let _ = DB_READS.set(DbReadQueue { jobs: Default::default(), ready: Default::default() });
    for _ in 0..DB_READERS {
        let mut __reader = rusqlite::Connection::open(&path).map_err(|e| format!("database {path}: cannot open a reader connection: {e}"))?;
        db_connection_setup(&mut __reader).map_err(|e| format!("database {path}: {e}"))?;
        __reader.pragma_update(None, "query_only", true).map_err(|e| format!("database {path}: cannot make a reader query_only: {e}"))?;
        std::thread::Builder::new()
            .name("db-reader".into())
            .spawn(move || db_reader(__reader))
            .map_err(|e| format!("database {path}: cannot start a reader: {e}"))?;
    }
    Ok(())
}

const DB_MIGRATIONS: &[(&str, &str, &str)] = &[
    ("001_create_notes.sql", "3875edf5066ca02a687866c76a13272020b755c69416b16376efbff3a4a3db11", "CREATE TABLE notes (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  body TEXT NOT NULL,\n  created_at TEXT NOT NULL,\n  tag TEXT\n);\n"),
];

const DB_STATEMENTS: &[(&str, &str, &str, u8, &[&str])] = &[
    ("recent_notes", "examples/notes.axum.rb:26", DB_SQL_RECENT_NOTES, 2, &["id", "body", "created_at", "tag"]),
    ("find_note", "examples/notes.axum.rb:30", DB_SQL_FIND_NOTE, 2, &["id", "body", "created_at", "tag"]),
    ("add_note", "examples/notes.axum.rb:32", DB_SQL_ADD_NOTE, 1, &[]),
    ("delete_note", "examples/notes.axum.rb:36", DB_SQL_DELETE_NOTE, 0, &[]),
];

// Per-connection settings, run on the writer's and every reader's connection (journal_mode=WAL is a property of
// the database file and is set once in db_startup). The statement cache holds every declared statement,
// at least rusqlite's default of 16, so prepare_cached never evicts one it will need again.
fn db_connection_setup(__c: &mut rusqlite::Connection) -> Result<(), String> {
    __c.execute_batch("PRAGMA synchronous=NORMAL; PRAGMA cache_size=2000; PRAGMA journal_size_limit=67108864;")
        .map_err(|e| format!("database: cannot set the connection pragmas: {e}"))?;
    __c.set_prepared_statement_cache_capacity(16);
    __c.wal_hook(Some(db_note_wal_size))
        .map_err(|e| format!("database: cannot install the WAL hook: {e}"))?;
    Ok(())
}

// Checkpoints run off the committing request (once-campfire-rust/crates/db/src/database.rs, measured in
// plans/perf-attribution.md): the WAL hook below replaces SQLite's auto-checkpoint and only notes the WAL size.
const DB_AUTOCHECKPOINT_PAGES: i32 = 1000;
const DB_WAL_LIMIT_PAGES: i32 = 10_000;
static DB_WAL_PAGES: std::sync::atomic::AtomicI32 = std::sync::atomic::AtomicI32::new(0);
static DB_WOKEN_AT: std::sync::atomic::AtomicI32 = std::sync::atomic::AtomicI32::new(0);
static DB_WAKE: std::sync::OnceLock<std::sync::mpsc::SyncSender<()>> = std::sync::OnceLock::new();
// Held while the checkpointer runs, so a RESTART waits for it rather than being refused.
static DB_CHECKPOINT_RUNNING: std::sync::Mutex<()> = std::sync::Mutex::new(());

// SQLite calls this only for a commit that wrote frames, so a write that changed nothing (an UPDATE whose
// WHERE matched no row) does not move the response cache's generation.
fn db_note_wal_size(_: &mut rusqlite::hooks::Wal, pages: std::os::raw::c_int) -> rusqlite::Result<()> {
    DB_WAL_PAGES.store(pages, std::sync::atomic::Ordering::Relaxed);
    Ok(())
}

// After a write on `__c`: wake the checkpointer per 1,000 pages the WAL grew, RESTART it past 10,000.
fn db_after_write(__c: &rusqlite::Connection) {
    match DB_WAL_PAGES.swap(0, std::sync::atomic::Ordering::Relaxed) {
        0 => {}
        pages if pages >= DB_WAL_LIMIT_PAGES => {
            let _running = DB_CHECKPOINT_RUNNING.lock().unwrap_or_else(|p| p.into_inner());
            db_checkpoint(__c, "RESTART");
        }
        pages => {
            let woken_at = DB_WOKEN_AT.load(std::sync::atomic::Ordering::Relaxed);
            if pages < woken_at {
                DB_WOKEN_AT.store(0, std::sync::atomic::Ordering::Relaxed); // the WAL restarted
            }
            let woken_at = DB_WOKEN_AT.load(std::sync::atomic::Ordering::Relaxed);
            // While a checkpoint is still due (the channel is full), the next write tries again.
            if pages - woken_at >= DB_AUTOCHECKPOINT_PAGES && DB_WAKE.get().is_some_and(|w| w.try_send(()).is_ok()) {
                DB_WOKEN_AT.store(pages, std::sync::atomic::Ordering::Relaxed);
            }
        }
    }
}

// A checkpoint that could not finish is reported in the `busy` column, not as an error.
fn db_checkpoint(__c: &rusqlite::Connection, mode: &str) {
    match __c.query_row(&format!("PRAGMA wal_checkpoint({mode})"), [], |__r| __r.get::<_, i64>(0)) {
        Ok(0) => {}
        Ok(_) => eprintln!("database: WAL checkpoint {mode} could not finish"),
        Err(e) => eprintln!("database: WAL checkpoint {mode} failed: {e}"),
    }
}

fn db_startup(__c: &mut rusqlite::Connection) -> Result<(), String> {
    __c.execute_batch("PRAGMA journal_mode=WAL;")
        .map_err(|e| format!("database: cannot set journal_mode=WAL: {e}"))?;
    __c.execute_batch("CREATE TABLE IF NOT EXISTS axum_dsl_migrations (version TEXT PRIMARY KEY, sha256 TEXT NOT NULL, applied_at TEXT NOT NULL);")
        .map_err(|e| format!("database: cannot create axum_dsl_migrations: {e}"))?;
    for &(__file, __sha, __sql) in DB_MIGRATIONS {
        let __done: Option<String> = rusqlite::OptionalExtension::optional(
            __c.query_row("SELECT sha256 FROM axum_dsl_migrations WHERE version = ?1", rusqlite::params![__file], |__r| __r.get(0)),
        )
        .map_err(|e| format!("migration {__file}: {e}"))?;
        match __done {
            Some(__applied) if __applied == __sha => continue,
            Some(__applied) => {
                return Err(format!(
                    "migration {__file} was changed after it was applied: the database recorded sha256 {__applied}, the file now has {__sha}; add a new migration instead of editing an applied one"
                ));
            }
            None => {}
        }
        let __tx = __c.transaction().map_err(|e| format!("migration {__file}: {e}"))?;
        __tx.execute_batch(__sql).map_err(|e| format!("migration {__file}: {e}"))?;
        __tx.execute(
            "INSERT INTO axum_dsl_migrations (version, sha256, applied_at) VALUES (?1, ?2, datetime('now'))",
            rusqlite::params![__file, __sha],
        )
        .map_err(|e| format!("migration {__file}: {e}"))?;
        __tx.commit().map_err(|e| format!("migration {__file}: {e}"))?;
    }
    let mut __writes = Vec::with_capacity(DB_STATEMENTS.len());
    for &(__name, __at, __sql, __check, __fields) in DB_STATEMENTS {
        let __stmt = __c.prepare(__sql).map_err(|e| format!("{__at}: query `{__name}`: {e}"))?;
        __writes.push(!__stmt.readonly());
        match __check {
            1 if __stmt.column_count() == 0 => {
                return Err(format!("{__at}: query `{__name}` returns no columns, but it is declared to return a single value"));
            }
            2 => {
                let __got: Vec<String> = __stmt.column_names().into_iter().map(|__n| __n.to_string()).collect();
                db_columns(__at, __name, &__got, __fields)?;
            }
            _ => {}
        }
    }
    let _ = DB_WRITES.set(__writes);
    Ok(())
}

// `--schema-check`: the startup path above on a fresh in-memory database, which needs neither the settings nor the
// writer, reader and checkpointer threads and leaves no file behind. Exit status 0 when every statement prepares
// and returns its record's columns, 2 with the startup message when not.
fn db_schema_check() -> i32 {
    let mut __c = match rusqlite::Connection::open_in_memory() {
        Ok(c) => c,
        Err(e) => {
            eprintln!("database: cannot open an in-memory database: {e}");
            return 2;
        }
    };
    match db_connection_setup(&mut __c).and_then(|_| db_startup(&mut __c)) {
        Ok(()) => {
            println!("schema-check: ok, {} statement(s) prepared", DB_STATEMENTS.len());
            0
        }
        Err(message) => {
            eprintln!("{message}");
            2
        }
    }
}

// `--console DB_PATH` (docs/console.md): a read-only line protocol over the declared statements, for axum_dsl console.
fn db_console_table() -> &'static [(&'static str, &'static str, &'static str, u8, &'static [&'static str])] {
    DB_STATEMENTS
}

fn db_console_applied(c: &rusqlite::Connection) -> std::collections::HashMap<String, String> {
    let read = || -> rusqlite::Result<std::collections::HashMap<String, String>> {
        let mut stmt = c.prepare("SELECT version, sha256 FROM axum_dsl_migrations")?;
        let rows = stmt.query_map([], |r| Ok((r.get::<_, String>(0)?, r.get::<_, String>(1)?)))?;
        rows.collect()
    };
    read().unwrap_or_default()
}

fn db_console(path: Option<String>) -> i32 {
    use std::io::{BufRead, Write};
    let Some(path) = path else {
        eprintln!("usage: --console DB_PATH");
        return 2;
    };
    if !std::path::Path::new(&path).is_file() {
        eprintln!("console: no database file at {path}");
        return 2;
    }
    let mut c = match rusqlite::Connection::open(&path) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("console: cannot open {path}: {e}");
            return 2;
        }
    };
    if let Err(message) = db_connection_setup(&mut c) {
        eprintln!("{message}");
        return 2;
    }
    if let Err(e) = c.pragma_update(None, "query_only", true) {
        eprintln!("console: cannot make the connection query_only: {e}");
        return 2;
    }
    let applied = db_console_applied(&c);
    let mut pending: Vec<String> = Vec::new();
    for &(file, sha, _) in DB_MIGRATIONS {
        match applied.get(file) {
            None => pending.push(file.to_string()),
            Some(got) if got.as_str() != sha => pending.push(format!("{file} (changed after it was applied)")),
            Some(_) => {}
        }
    }
    if !pending.is_empty() {
        eprintln!("console: {path} has migrations that are not applied: {}; start the server once to apply them", pending.join(", "));
        return 2;
    }
    let mut out = std::io::stdout().lock();
    let _ = writeln!(out, "{}", ::serde_json::json!({ "ready": true, "statements": db_console_table().len() }));
    let _ = out.flush();
    for line in std::io::stdin().lock().lines() {
        let Ok(line) = line else { break };
        if line.trim().is_empty() {
            continue;
        }
        let reply = db_console_line(&c, &line).unwrap_or_else(|e| ::serde_json::json!({ "error": e }));
        if writeln!(out, "{reply}").and_then(|_| out.flush()).is_err() {
            break;
        }
    }
    0
}

// One request line: the statement DB_STATEMENTS names, its named parameters bound from `args`, every row as JSON.
fn db_console_line(c: &rusqlite::Connection, line: &str) -> Result<::serde_json::Value, String> {
    let req: ::serde_json::Value = ::serde_json::from_str(line).map_err(|e| format!("the request is not JSON: {e}"))?;
    let name = req.get("stmt").and_then(|v| v.as_str()).ok_or_else(|| "the request needs a \"stmt\" name".to_string())?;
    let none = ::serde_json::Map::new();
    let args = match req.get("args") {
        None | Some(::serde_json::Value::Null) => &none,
        Some(::serde_json::Value::Object(m)) => m,
        Some(_) => return Err("\"args\" must be an object".to_string()),
    };
    let found: Vec<_> = db_console_table().iter().filter(|s| s.0 == name).collect();
    if found.is_empty() {
        return Err(format!("no statement `{name}`"));
    }
    for s in &found {
        let probe = c.prepare(s.2).map_err(|e| format!("statement `{name}`: {e}"))?;
        if !probe.readonly() {
            return Err(format!("statement `{name}` writes, and the console is read-only"));
        }
    }
    let started = std::time::Instant::now();
    let mut stmt = c.prepare(found[0].2).map_err(|e| format!("statement `{name}`: {e}"))?;
    let mut names: Vec<String> = Vec::new();
    for i in 1..=stmt.parameter_count() {
        let pname = stmt
            .parameter_name(i)
            .map(|p| p.trim_start_matches([':', '@', '$']).to_string())
            .ok_or_else(|| format!("statement `{name}` has a positional parameter"))?;
        let value = args.get(&pname).ok_or_else(|| format!("statement `{name}` needs the argument `{pname}`"))?;
        let bound = match value {
            ::serde_json::Value::Null => rusqlite::types::Value::Null,
            ::serde_json::Value::Bool(b) => rusqlite::types::Value::Integer(i64::from(*b)),
            ::serde_json::Value::Number(n) => match (n.as_i64(), n.as_f64()) {
                (Some(i), _) => rusqlite::types::Value::Integer(i),
                (None, Some(f)) => rusqlite::types::Value::Real(f),
                _ => return Err(format!("argument `{pname}` is not a number SQLite can bind")),
            },
            ::serde_json::Value::String(s) => rusqlite::types::Value::Text(s.clone()),
            _ => return Err(format!("argument `{pname}` must be a number, a string, a bool or null")),
        };
        stmt.raw_bind_parameter(i, bound).map_err(|e| format!("argument `{pname}`: {e}"))?;
        names.push(pname);
    }
    if let Some(extra) = args.keys().find(|k| !names.contains(k)) {
        return Err(format!("statement `{name}` takes no argument `{extra}`"));
    }
    let columns: Vec<String> = stmt.column_names().into_iter().map(|n| n.to_string()).collect();
    let mut rows = stmt.raw_query();
    let mut out: Vec<::serde_json::Value> = Vec::new();
    while let Some(row) = rows.next().map_err(|e| format!("statement `{name}`: {e}"))? {
        let mut cells = Vec::with_capacity(columns.len());
        for i in 0..columns.len() {
            let cell = match row.get_ref(i).map_err(|e| format!("statement `{name}`: {e}"))? {
                rusqlite::types::ValueRef::Null => ::serde_json::Value::Null,
                rusqlite::types::ValueRef::Integer(n) => ::serde_json::Value::from(n),
                rusqlite::types::ValueRef::Real(f) => ::serde_json::Number::from_f64(f).map_or(::serde_json::Value::Null, ::serde_json::Value::Number),
                rusqlite::types::ValueRef::Text(t) => ::serde_json::Value::String(String::from_utf8_lossy(t).into_owned()),
                rusqlite::types::ValueRef::Blob(b) => ::serde_json::Value::String(format!("<blob, {} bytes>", b.len())),
            };
            cells.push(cell);
        }
        out.push(::serde_json::Value::Array(cells));
    }
    let ms = (started.elapsed().as_secs_f64() * 100_000.0).round() / 100.0;
    Ok(::serde_json::json!({ "columns": columns, "rows": out, "ms": ms }))
}

fn db_columns(at: &str, name: &str, got: &[String], fields: &[&str]) -> Result<(), String> {
    let missing: Vec<&str> = fields.iter().copied().filter(|f| !got.iter().any(|g| g == f)).collect();
    let extra: Vec<&str> = got.iter().map(|g| g.as_str()).filter(|g| !fields.contains(g)).collect();
    if missing.is_empty() && extra.is_empty() {
        return Ok(());
    }
    Err(format!(
        "{at}: query `{name}` does not select the columns of its record: missing {missing:?}, not a field {extra:?}"
    ))
}

const DB_SQL_RECENT_NOTES: &str = "SELECT id, body, created_at, tag FROM notes ORDER BY id DESC LIMIT :limit\n";

fn query_recent_notes_on(__c: &rusqlite::Connection, limit: i64) -> rusqlite::Result<Vec<Note>> {
    let mut __stmt = __c.prepare_cached(DB_SQL_RECENT_NOTES)?;
    let __rows = __stmt.query_map(rusqlite::named_params! { ":limit": limit }, Note::from_row)?;
    let __out = __rows.collect::<rusqlite::Result<Vec<Note>>>();
    __out
}

async fn query_recent_notes(limit: i64) -> Result<Vec<Note>, String> {
    db_run(0, "recent_notes", move |__c| query_recent_notes_on(__c, limit))
    .await
}

const DB_SQL_FIND_NOTE: &str = "SELECT id, body, created_at, tag FROM notes WHERE id = :id";

fn query_find_note_on(__c: &rusqlite::Connection, id: i64) -> rusqlite::Result<Option<Note>> {
    let mut __stmt = __c.prepare_cached(DB_SQL_FIND_NOTE)?;
    let __out = rusqlite::OptionalExtension::optional(__stmt.query_row(rusqlite::named_params! { ":id": id }, Note::from_row));
    __out
}

async fn query_find_note(id: i64) -> Result<Option<Note>, String> {
    db_run(1, "find_note", move |__c| query_find_note_on(__c, id))
    .await
}

const DB_SQL_ADD_NOTE: &str = "INSERT INTO notes (body, created_at) VALUES (:body, datetime('now')) RETURNING id\n";

fn query_add_note_on(__c: &rusqlite::Connection, body: String) -> rusqlite::Result<i64> {
    let mut __stmt = __c.prepare_cached(DB_SQL_ADD_NOTE)?;
    let __out = __stmt.query_row(rusqlite::named_params! { ":body": body }, |__r| __r.get::<_, i64>(0));
    __out
}

async fn query_add_note(body: String) -> Result<i64, String> {
    db_run(2, "add_note", move |__c| query_add_note_on(__c, body))
    .await
}

const DB_SQL_DELETE_NOTE: &str = "DELETE FROM notes WHERE id = :id";

fn query_delete_note_on(__c: &rusqlite::Connection, id: i64) -> rusqlite::Result<i64> {
    let mut __stmt = __c.prepare_cached(DB_SQL_DELETE_NOTE)?;
    let __out = __stmt.execute(rusqlite::named_params! { ":id": id }).map(|__n| __n as i64);
    __out
}

async fn query_delete_note(id: i64) -> Result<i64, String> {
    db_run(3, "delete_note", move |__c| query_delete_note_on(__c, id))
    .await
}

fn internal_error(message: &str) -> ::axum::response::Response {
    let mut response = ::axum::response::IntoResponse::into_response(message.to_string());
    *response.status_mut() = ::axum::http::StatusCode::INTERNAL_SERVER_ERROR;
    response
}

fn error_response(message: &str) -> ::axum::response::Response {
    internal_error(message)
}

#[allow(unused_variables)]
async fn route_1(axum::extract::Form(__form): axum::extract::Form<NewNote>) -> ::axum::response::Response {
    let NewNote { body } = __form;
    let response = match (async || -> Result<::axum::response::Response, String> {
        Ok(::axum::response::IntoResponse::into_response(query_add_note(body.clone()).await?.to_string()))
    })().await {
        Ok(response) => response,
        Err(message) => error_response(&message),
    };
    response
}

async fn route_2() -> ::axum::response::Response {
    let response = match (async || -> Result<::axum::response::Response, String> {
        Ok(::axum::response::IntoResponse::into_response(::axum::Json(query_recent_notes(20).await?)))
    })().await {
        Ok(response) => response,
        Err(message) => error_response(&message),
    };
    response
}

async fn route_3() -> ::axum::response::Response {
    let response = match (async || -> Result<::axum::response::Response, String> {
        Ok(::axum::response::IntoResponse::into_response(::axum::response::Html({ let mut __out = String::with_capacity(190); __out.push_str("<!doctype html>\n<html lang=\"en\">\n<head><title>Notes</title></head>\n<body>\n<ul>\n"); for __it_note in &query_recent_notes(20).await? { __out.push_str("\n  <li id=\"note-"); let _ = ::std::fmt::Write::write_fmt(&mut __out, format_args!("{}", __it_note.id)); __out.push_str("\">"); axum_dsl_html_escape_into(&mut __out, &__it_note.body); __out.push_str(" <small>"); axum_dsl_html_escape_into(&mut __out, &__it_note.created_at); __out.push_str("</small></li>\n"); } __out.push_str("\n</ul>\n</body>\n</html>\n"); __out })))
    })().await {
        Ok(response) => response,
        Err(message) => error_response(&message),
    };
    response
}

#[allow(unused_variables)]
async fn route_4(axum::extract::Path(__path): axum::extract::Path<NoteId>) -> ::axum::response::Response {
    let NoteId { id } = __path;
    let response = match (async || -> Result<::axum::response::Response, String> {
        let note = query_find_note(id).await?;
        Ok(match note { None => { { let mut __halted = ::axum::response::IntoResponse::into_response("no such note".to_string()); *__halted.status_mut() = ::axum::http::StatusCode::from_u16(404).unwrap(); __halted } }, Some(note) => { ::axum::response::IntoResponse::into_response(::axum::Json(note)) } })
    })().await {
        Ok(response) => response,
        Err(message) => error_response(&message),
    };
    response
}

#[allow(unused_variables)]
async fn route_5(axum::extract::Path(__path): axum::extract::Path<NoteId>) -> ::axum::response::Response {
    let NoteId { id } = __path;
    let response = match (async || -> Result<::axum::response::Response, String> {
        Ok(::axum::response::IntoResponse::into_response(query_delete_note(id).await?.to_string()))
    })().await {
        Ok(response) => response,
        Err(message) => error_response(&message),
    };
    response
}

// Resolves on ctrl-c or SIGTERM, so the server stops taking connections and drains: written by the compiler
async fn shutdown_signal() {
    let ctrl_c = async {
        tokio::signal::ctrl_c().await.expect("cannot listen for ctrl-c");
    };
    #[cfg(unix)]
    let terminate = async {
        tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())
            .expect("cannot listen for SIGTERM")
            .recv()
            .await;
    };
    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();
    tokio::select! {
        _ = ctrl_c => {}
        _ = terminate => {}
    }
}

// jemalloc as the global allocator, and no transparent huge pages on Linux: written by the compiler
#[global_allocator]
static GLOBAL: tikv_jemallocator::Jemalloc = tikv_jemallocator::Jemalloc;

// jemalloc reads its options from this exported symbol (tikv-jemallocator's `_rjem_` prefix) when it
// starts, before main. It is a `const char *`, so a thin pointer to the first byte.
#[cfg(target_os = "linux")]
#[allow(unsafe_code)]
#[unsafe(export_name = "_rjem_malloc_conf")]
pub static JEMALLOC_CONF: Option<&'static std::ffi::c_char> =
    // SAFETY: points at the first byte of a static, NUL-terminated string.
    Some(unsafe { &*c"thp:never".as_ptr() });

// With transparent huge pages set to `always`, every thread stack gets backed by whole 2 MB pages as
// soon as it is touched; nothing here is big enough to gain from them, so the process opts out.
#[allow(unsafe_code)]
fn disable_transparent_huge_pages() {
    #[cfg(target_os = "linux")]
    {
        let off: libc::c_ulong = 1;
        // SAFETY: PR_SET_THP_DISABLE takes machine-width integer arguments and only changes this
        // process's memory policy.
        if unsafe { libc::prctl(libc::PR_SET_THP_DISABLE, off, 0 as libc::c_ulong, 0 as libc::c_ulong, 0 as libc::c_ulong) } != 0 {
            eprintln!("couldn't disable transparent huge pages: {}", std::io::Error::last_os_error());
        }
    }
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    disable_transparent_huge_pages();
    if std::env::args().nth(1).as_deref() == Some("--console") {
        std::process::exit(db_console(std::env::args().nth(2)));
    }
    if std::env::args().nth(1).as_deref() == Some("--schema-check") {
        std::process::exit(db_schema_check());
    }
    if let Err(message) = db_open().await {
        eprintln!("{message}");
        std::process::exit(2);
    }
    let router = axum::Router::new()
        .route("/notes", axum::routing::post(route_1))
        .route("/notes", axum::routing::get(route_2))
        .route("/notes.html", axum::routing::get(route_3))
        .route("/notes/{id}", axum::routing::get(route_4))
        .route("/notes/{id}", axum::routing::delete(route_5));
    let port = match std::env::var("PORT") {
        Ok(value) => match value.parse::<u16>() {
            Ok(port) => port,
            Err(_) => {
                eprintln!("PORT must be a port number from 0 to 65535, got {value:?}");
                std::process::exit(2);
            }
        },
        Err(_) => 8084,
    };
    let bind = std::env::var("BIND").unwrap_or_else(|_| "127.0.0.1".to_string());
    let listener = tokio::net::TcpListener::bind((bind.as_str(), port)).await?;
    axum::serve(listener, router.into_make_service_with_connect_info::<std::net::SocketAddr>())
        .with_graceful_shutdown(shutdown_signal())
        .await?;
    Ok(())
}
